# HOG orientation histogram on a synthetic car side view
import math
W,H=16,10
img=[[40]*W for _ in range(H)]
for y in range(5,9):
    for x in range(1,15): img[y][x]=150                    # body
for y in range(3,5):
    for x in range(4,12): img[y][x]=150                   # cabin
for (cx,cy) in ((4,8),(12,8)):                            # wheels
    for y in range(H):
        for x in range(W):
            if (x-cx)**2+(y-cy)**2<=4: img[y][x]=30
hist=[0.0]*9
for y in range(1,H-1):
    for x in range(1,W-1):
        gx=img[y][x+1]-img[y][x-1]; gy=img[y+1][x]-img[y-1][x]
        b=int((math.degrees(math.atan2(gy,gx))%180)//20)%9
        hist[b]+=math.hypot(gx,gy)
tot=sum(hist)
print("car side-view HOG (9 bins, 0-180 deg):")
for i,v in enumerate(hist):
    print("  bin %d (%3d-%3d): %7.1f %s" % (i,i*20,i*20+20,v,'#'*int(30*v/tot)))
print("Horizontals (roof) + verticals (pillars) + spread (wheel arcs): car shape as statistics.")

# Harris corner response on corner vs edge vs flat patches
GX=[[-1,0,1],[-2,0,2],[-1,0,1]]; GY=[[-1,-2,-1],[0,0,0],[1,2,1]]
def harris(im):
    h,w=len(im),len(im[0])
    Ix=[[0]*w for _ in range(h)]; Iy=[[0]*w for _ in range(h)]
    for y in range(1,h-1):
        for x in range(1,w-1):
            Ix[y][x]=sum(im[y+ky-1][x+kx-1]*GX[ky][kx] for ky in range(3) for kx in range(3))
            Iy[y][x]=sum(im[y+ky-1][x+kx-1]*GY[ky][kx] for ky in range(3) for kx in range(3))
    a=b=c=0.0
    for y in range(2,5):
        for x in range(2,5):
            a+=Ix[y][x]**2; b+=Ix[y][x]*Iy[y][x]; c+=Iy[y][x]**2
    return (a*c-b*b)-0.04*(a+c)**2
corner=[[0]*7 for _ in range(7)]
for y in range(3,7):
    for x in range(3,7): corner[y][x]=100
edge=[[0 if x<3 else 100 for x in range(7)] for _ in range(7)]
flat=[[50]*7 for _ in range(7)]
for name,im in (("corner patch",corner),("edge patch  ",edge),("flat patch  ",flat)):
    print("%s Harris R = %12.0f" % (name,harris(im)))
print("R>>0 corner, R<<0 edge, R~0 flat: Harris & Stephens (1988), executed.")

# LoG blob detection: 5x5 kernel on a matched blob vs an oversized blob
LOG=[[0,0,-1,0,0],[0,-1,-2,-1,0],[-1,-2,16,-2,-1],[0,-1,-2,-1,0],[0,0,-1,0,0]]
def apply(im,k):
    h,w=len(im),len(im[0]); o=[[0]*w for _ in range(h)]
    for y in range(2,h-2):
        for x in range(2,w-2):
            o[y][x]=sum(im[y+dy-2][x+dx-2]*k[dy][dx] for dy in range(5) for dx in range(5))
    return o
def blob(sz,r):
    im=[[0]*sz for _ in range(sz)]
    c=sz//2
    for y in range(sz):
        for x in range(sz):
            if (x-c)**2+(y-c)**2<=r*r: im[y][x]=100
    return im
for name,im in (("matched blob (r=2)",blob(9,2)),("oversized blob (r=4)",blob(13,4))):
    o=apply(im,LOG); c=len(im)//2
    print("%-20s center response = %d (documented blob signature: strong center)" % (name,o[c][c]))
print("LoG is scale-tuned: matched size fires, wrong size weakens -> search scale space (SIFT/DoG).")
